import FxsActivatable, { ActionActivateEventName } from "#core/ui/components/fxs-activatable.js";

export class FxsLink extends FxsActivatable {
	onAttach() {
		super.onAttach();

		this.Root.addEventListener(ActionActivateEventName, () => {
			const key = this.Root.getAttribute("url") as keyof typeof URLType;

			if (key) {
				Network.openURLFromType(URLType[key]);
			}
		});
	}
}

Controls.define("fxs-link", {
	createInstance: FxsLink,
	description: "An hyperlink",
	attributes: [
		{
			name: "url",
			description: "the predefined possible url",
		},
	],
});
